fn try_from(value: String) -> Result<Self, Self::Error> {
    if valid_identifier(&value) {
        Ok(Self(value))
    } else {
        Err(ContractError::InvalidIdentifier)
    }
}

fn try_from(value: &str) -> Result<Self, Self::Error> {
    Self::try_from(value.to_owned())
}

pub fn as_str(&self) -> &str {
    &self.0
}

fn from(value: $name) -> Self {
    value.0
}

fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
where
    D: serde::Deserializer<'de>,
{
    let value = <String as Deserialize>::deserialize(deserializer)?;
    // Same primitive decode, conversion and error as serde's
    // try_from derive; the explicit closure is extractable.
    Self::try_from(value).map_err(|error| serde::de::Error::custom(error))
}

fn try_from(value: u64) -> Result<Self, Self::Error> {
    if value == 0 {
        Err(InternalError::InvalidCounter)
    } else {
        Ok(Self(value))
    }
}

pub const fn get(self) -> u64 {
    self.0
}

pub fn checked_next(self) -> Result<Self, InternalError> {
    match self.get().checked_add(1) {
        Some(value) => Self::try_from(value),
        None => Err(InternalError::InvalidCounter),
    }
}

fn from(value: PositiveCounter) -> Self {
    value.get()
}

fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
where
    D: serde::Deserializer<'de>,
{
    let value = <u64 as Deserialize>::deserialize(deserializer)?;
    Self::try_from(value).map_err(|error| serde::de::Error::custom(error))
}

pub struct NodeIdentity {
    pub deployment_id: DeploymentId,
    pub node_id: NodeId,
    pub node_generation: PositiveCounter,
}

pub struct ControlIdentity {
    pub protocol_version: u16,
    pub node: NodeIdentity,
    pub tenant_id: TenantId,
    pub sandbox_id: SandboxId,
    pub operation_id: OperationId,
    pub intent_version: PositiveCounter,
    /// A bounded protected inbox position, not a native VM or public identifier.
    pub retention_slot: u16,
    /// Incarnation of this ONE retention slot, never a node-wide window.
    pub request_window: PositiveCounter,
}

pub fn validate_node(&self, expected: &NodeIdentity) -> Result<(), InternalError> {
    validate_version(self.protocol_version)?;
    validate_node(&self.node, expected)?;
    if self.retention_slot == 0 {
        return Err(InternalError::BindingMismatch);
    }
    Ok(())
}

pub fn validate_response(&self, expected: &Self) -> Result<(), InternalError> {
    self.validate_node(&expected.node)?;
    expected.validate_node(&expected.node)?;
    if self == expected {
        Ok(())
    } else {
        Err(InternalError::BindingMismatch)
    }
}

pub fn validate(&self, expected: &NodeIdentity) -> Result<(), InternalError> {
    validate_version(self.protocol_version)?;
    validate_node(&self.node, expected)
}

pub fn validate_for(&self, request: &ProbeRequest) -> Result<(), InternalError> {
    request.validate(&self.node)?;
    validate_version(self.protocol_version)?;
    if self.request_id == request.request_id {
        Ok(())
    } else {
        Err(InternalError::BindingMismatch)
    }
}

pub const fn values(self) -> [u64; 4] {
    [self.instances, self.cpu, self.memory_bytes, self.disk_bytes]
}

pub fn positive(self) -> bool {
    self.instances > 0 && self.cpu > 0 && self.memory_bytes > 0 && self.disk_bytes > 0
}

pub fn checked_add(self, other: Self) -> Option<Self> {
    Some(Self {
        instances: self.instances.checked_add(other.instances)?,
        cpu: self.cpu.checked_add(other.cpu)?,
        memory_bytes: self.memory_bytes.checked_add(other.memory_bytes)?,
        disk_bytes: self.disk_bytes.checked_add(other.disk_bytes)?,
    })
}

pub fn fits(self, limit: Self) -> bool {
    self.instances <= limit.instances
        && self.cpu <= limit.cpu
        && self.memory_bytes <= limit.memory_bytes
        && self.disk_bytes <= limit.disk_bytes
}

pub fn seconds_to_milliseconds(seconds: u64) -> Option<u64> {
    seconds.checked_mul(1000)
}

pub fn bytes_to_mebibytes(bytes: u64) -> Option<u32> {
    let whole = bytes / (1024 * 1024);
    let extra = match bytes % (1024 * 1024) {
        0 => 0,
        _ => 1,
    };
    // whole is at most 2^44 - 1, so this addition cannot overflow U64.
    let units = whole + extra;
    if units > u64::from(u32::MAX) {
        None
    } else {
        Some(units as u32)
    }
}

pub fn available_resource(limit: u64, used: u64, observed: u64) -> u64 {
    let remaining = limit.saturating_sub(used);
    if remaining < observed {
        remaining
    } else {
        observed
    }
}

fn checked_deadline(now_ms: i64, seconds: u64) -> Result<i64, AdmissionError> {
    if now_ms < 0 {
        return Err(AdmissionError::InvalidClock);
    }
    if seconds == 0 {
        return Err(AdmissionError::InvalidTimeout);
    }
    let milliseconds = seconds_to_milliseconds(seconds).ok_or(AdmissionError::TimeOverflow)?;
    now_ms
        .checked_add(i64::try_from(milliseconds).map_err(|_| AdmissionError::TimeOverflow)?)
        .ok_or(AdmissionError::TimeOverflow)
}

pub fn internal_free_resources(
    &self,
    node: &NodeIdentity,
    compute: ComputeLimits,
) -> Result<(u64, Resources), ApplicationError> {
    let inner = self.inner.lock().map_err(|_| ApplicationError::Busy)?;
    let slots =
        inner
            .journal
            .internal_available_instances(node)
            .map_err(|error| match error {
                JournalError::Conflict => ApplicationError::Invalid,
                other => map_journal(other),
            })?;
    let usage = inner
        .journal
        .retained_resource_usage()
        .map_err(map_admission)?;
    let bounded = inner
        .journal
        .bounded_host_config()
        .map_err(map_journal)?
        .ok_or(ApplicationError::Busy)?;
    let profile = bounded.physical_storage.ok_or(ApplicationError::Busy)?;
    let pool = profile
        .pool(inner.journal.deployment_namespace())
        .map_err(map_journal)?;
    inner.host.validate_physical_storage(&profile, pool)?;
    let disk = inner
        .host
        .available_disk_bytes()?
        .saturating_sub(profile.peak_bytes().map_err(map_journal)?);
    let (cpu, memory) = inner.host.available_compute()?;
    let free = Resources {
        instances: available_resource(
            self.config.limits.max_active_global,
            usage.instances,
            slots,
        ),
        cpu: available_resource(compute.max_vcpus_global, usage.cpu, cpu),
        memory_bytes: available_resource(
            compute.max_memory_bytes_global,
            usage.memory_bytes,
            memory,
        ),
        disk_bytes: available_resource(pool.rootfs_budget_bytes, usage.disk_bytes, disk),
    };
    Ok((
        u64::try_from(self.clock.now_ms()?).map_err(|_| ApplicationError::Invalid)?,
        free,
    ))
}

pub fn parse_allocated_number(value: &str, prefix: &str, highwater: u64) -> Option<u64> {
    // The exact prefix is checked before parsing. split_at_checked avoids the
    // fixed translator's unsupported Pattern type without slicing invalid UTF-8.
    let (actual_prefix, suffix) = value.split_at_checked(prefix.len())?;
    if actual_prefix != prefix {
        return None;
    }
    let value = suffix.parse::<u64>().ok()?;
    (value > 0 && value <= highwater && value.to_string() == suffix).then_some(value)
}

pub fn number(value: &str, prefix: &str, highwater: u64) -> Option<u64> {
    sandproof_protocol::parse_allocated_number(value, prefix, highwater)
}

pub fn current(&self) -> Option<PositiveCounter> {
    self.retired_through.checked_add(1)?.try_into().ok()
}

pub struct ResourceRef {
    pub kind: ResourceKind,
    pub id: ResourceId,
}

pub const fn validate_version(&self) -> Result<(), ContractError> {
    if self.protocol_version == PROTOCOL_VERSION {
        Ok(())
    } else {
        Err(ContractError::UnsupportedVersion(self.protocol_version))
    }
}

pub fn validate_for<C>(&self, action: &WorkAction<C>) -> Result<(), ContractError> {
    action.identity.validate_version()?;
    self.identity.validate_version()?;
    if self.identity != action.identity {
        return Err(ContractError::MismatchedIdentity);
    }
    if self
        .outcome
        .observation()
        .is_some_and(|observation| observation.resource() != &action.identity.resource)
    {
        return Err(ContractError::MismatchedObservation);
    }
    Ok(())
}

pub const fn new(value: u64) -> Self {
    Self(value)
}

pub const fn value(self) -> u64 {
    self.0
}

pub struct LocalValidationBinding {
    pub owner: u64,
    pub sandbox: SandboxId,
    pub create_operation: OperationId,
    pub descriptor: TemplateBinding,
}

pub fn is_projection_of(&self, global: &TemplateBinding) -> bool {
    if self.owner == 0 || self.sandbox.0 == 0 || self.create_operation.0 == 0 {
        return false;
    }
    let mut expected = global.clone();
    expected.owner = Some(self.owner);
    expected
        .kernel
        .path
        .clone_from(&self.descriptor.kernel.path);
    expected
        .rootfs
        .path
        .clone_from(&self.descriptor.rootfs.path);
    expected == self.descriptor
        && self.descriptor.is_valid()
        && serde_json::to_vec(&self.descriptor)
            .is_ok_and(|bytes| bytes.len() <= CreateOptions::MAX_ENCODED_BYTES)
}

pub struct LifecycleRequest {
    pub identity: ControlIdentity,
    /// Every operation carries the original binding, including destroy-first.
    pub create: CreateBinding,
    pub intent: Intent,
}

pub fn validate(&self, node: &NodeIdentity) -> Result<(), InternalError> {
    self.identity.validate_node(node)?;
    if !self.create.is_valid() || matches!(self.intent, Intent::Renew { end_at_ms: 0 }) {
        return Err(InternalError::BindingMismatch);
    }
    Ok(())
}

pub struct StatusRequest {
    pub node: NodeIdentity,
}

pub struct HostStatus {
    pub node: NodeIdentity,
    /// Protected inbox capacity, not inferred from native IDs or physical slots.
    pub retention_slots: u16,
    pub observed_at_ms: u64,
    /// Conservative physical/local free capacity. It can only veto admission;
    /// center reservations are still counted separately by the pure core.
    pub free: Resources,
}

pub fn validate(&self, node: &NodeIdentity) -> Result<(), TransportError> {
    if self.node != *node {
        return Err(TransportError::Rejected);
    }
    Ok(())
}

pub fn validate_for(&self, request: &StatusRequest) -> Result<(), TransportError> {
    if self.node != request.node || self.retention_slots == 0 || self.retention_slots > 4096 {
        return Err(TransportError::InvalidResponse);
    }
    Ok(())
}

pub struct ContractVersions {
    pub internal_protocol: u16,
    pub center_store: u32,
    pub host_store: i64,
}

pub const fn current() -> Self {
    Self {
        internal_protocol: INTERNAL_PROTOCOL_VERSION,
        center_store: CENTER_STORE_FORMAT_VERSION,
        host_store: HOST_STORE_FORMAT_VERSION,
    }
}

pub struct TemplateBinding {
    pub template_id: String,
    pub revision: String,
    /// None is an explicitly shared preinstalled template; private owners are nonzero.
    pub owner: Option<u64>,
    pub kernel: TemplateArtifact,
    pub rootfs: TemplateArtifact,
    pub resources: ResourceShape,
    pub envd_version: String,
    /// Exact Rust runtime/configuration identity, independent of the SDK's
    /// envd version negotiation. Absent in existing fixed-Go descriptors.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub guest: Option<TemplateGuest>,
    /// Normalized OCI defaults. Absent for legacy prebuilt images, whose cwd
    /// remains envd's per-user home. Frozen with the full admitted descriptor.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub startup: Option<TemplateStartup>,
}

pub struct Query {
    pub path: Option<Vec<u8>>,
    pub username: Option<Vec<u8>>,
    pub signature: Option<Vec<u8>>,
    pub signature_expiration: Option<i64>,
}

pub fn into_text(self) -> Result<TextQuery, Error> {
    let text = |value: Option<Vec<u8>>, parameter| {
        value
            .map(String::from_utf8)
            .transpose()
            .map_err(|_| Error::UnsupportedText(parameter))
    };
    Ok(TextQuery {
        path: text(self.path, Parameter::Path)?,
        username: text(self.username, Parameter::Username)?,
        signature: text(self.signature, Parameter::Signature)?,
        signature_expiration: self.signature_expiration,
    })
}

pub(crate) fn validate(&self) -> Result<(), ContextError> {
    if self.limits.path_bytes == 0
        || self.limits.path_bytes > isize::MAX as usize / 2
        || self.limits.username_bytes == 0
        || self.limits.authorization_bytes == 0
        || !self.daemon_workdir.starts_with('/')
        || self.daemon_workdir.contains('\0')
        || self.daemon_workdir.len() > self.limits.path_bytes
    {
        return Err(ContextError::InvalidArgument);
    }
    Ok(())
}
